"""Publish the pre-inference freeze without changing any previous study file."""
import hashlib
import json
import subprocess
from pathlib import Path

import docker

ROOT = Path(__file__).parent
REPO = Path('/home/zhongming/CodeNib-codegraph-benefit')
OUT = REPO / 'docs/experiments'
BASE = '3b3aaf5bd7a8b9cd1faa42d8d8c05e827b587bf2'
assert not (ROOT / 'sequential-launch-v2.json').exists()


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def write(name, value):
    path = OUT / name
    path.write_text(json.dumps(value, indent=2) + '\n')
    assert path.stat().st_size < 500 * 1024, (path.name, path.stat().st_size)
    return {'artifact': name, 'sha256': sha(path)}


direct = {
    'matched-tasks-v2.json': 'codegraph_matched_tasks_v2.json',
    'matched-policy-v4.json': 'codegraph_matched_policy_v4.json',
    'rubric-source-review-v2.json': 'codegraph_matched_source_review_v2.json',
    'execution-binding-v2.json': 'codegraph_matched_binding_v2.json',
    'execution-binding-v2-freeze.json': 'codegraph_matched_binding_v2_freeze.json',
}
published = {}
for source, name in direct.items():
    p = OUT / name
    p.write_bytes((ROOT / source).read_bytes())
    assert p.stat().st_size < 500 * 1024 and sha(p) == sha(ROOT / source)
    published[source] = {'artifact': name, 'sha256': sha(p)}
controllers = {sha(p): {'filename': p.name, 'source': p.read_text()} for p in ROOT.glob('*.py') if p.name != 'archive_protocol.py'}
inputs = {'scope': 'Exact independent v2 executable sources and pre-freeze descriptive drafts; no model outcomes.',
          'controllers': controllers,
          'python_constraints': {arm: (ROOT / 'constraints' / (arm + '.txt')).read_text() for arm in ['serena', 'codenib']},
          'pre_freeze_descriptive_drafts': {name: json.loads((ROOT / name).read_text()) for name in ['pre-freeze-policy-draft.json', 'pre-freeze-tasks-draft.json', 'pre-freeze-review-draft.json']},
          'archive_controller': {'sha256': sha(__file__), 'source': Path(__file__).read_text()}}
published['executables'] = write('codegraph_matched_v2_executables.json', inputs)
published['runtime_identities'] = write('codegraph_matched_v2_runtime_identities.json', {'products': json.loads((ROOT / 'expected-product-identities.json').read_text()), 'targets': json.loads((ROOT / 'expected-target-identities.json').read_text())})

refs, ids = [], set()
for generation in ['driver-validation-v2', 'driver-validation-v2-final', 'driver-validation-v2-corrected', 'driver-validation-v2-admitted']:
    for path in sorted((ROOT / generation).glob('*/receipt.json')):
        raw = json.loads(path.read_text())
        assert raw['driver_sha256'] in controllers
        assert all(c['removed'] for c in raw['cleanup'])
        ids.update(raw['owned_containers'])
        snapshots = {}
        for label in ['common_source', 'pre_model_source']:
            if label in raw:
                p = Path(raw[label]['path'])
                assert sha(p) == raw[label]['sha256']
                snapshots[label] = json.loads(p.read_text())
        value = {'generation': generation, 'original_receipt_sha256': sha(path), 'receipt': raw, 'source_snapshots': snapshots}
        error = path.parent / 'preflight-mcp.stderr'
        if error.exists():
            value['mcp_stderr'] = {'sha256': sha(error), 'text': error.read_text()}
        ref = write(f'codegraph_matched_v2_admission_{len(refs):02d}.json', value)
        ref.update(generation=generation, workflow=raw['workflow'], status=raw['status'])
        refs.append(ref)
assert len(refs) == 16
assert sum(r['status'] == 'prepared_no_inference' for r in refs) == 14
assert sum(r['status'] == 'error' for r in refs) == 2
uv = json.loads((ROOT / 'uv-options.json').read_text())
assert uv['container_removed']
ids.add(uv['container_id'])
engine = docker.from_env(timeout=60)
cleanup = []
try:
    for cid in sorted(ids):
        try: engine.containers.get(cid)
        except docker.errors.NotFound: cleanup.append({'container_id': cid, 'confirmed_absent': True})
        else: raise AssertionError('Pre-inference container remains: ' + cid)
finally:
    engine.close()

preserved = {}
for name in subprocess.check_output(['git', 'ls-tree', '-r', '--name-only', BASE, '--', 'docs/experiments'], cwd=REPO, text=True).splitlines():
    if Path(name).name.startswith('codegraph_') and name.endswith('.json'):
        assert subprocess.check_output(['git', 'show', BASE + ':' + name], cwd=REPO) == (REPO / name).read_bytes(), name
        preserved[name] = sha(REPO / name)
conformance = {}
for name in ['driver-conformance-v2-admitted/receipt.json', 'driver-usage-conformance-v2-admitted/assessment.json', 'terminal-conformance/assessment.json']:
    conformance[name] = {'sha256': sha(ROOT / name), 'receipt': json.loads((ROOT / name).read_text())}
artifact = {'schema_version': 1, 'scope': 'Prospective corrected v2 freeze and no-model admission, before the first new query. Original v1 tasks/outcomes and every previous study artifact remain unchanged.', 'source_baseline': BASE,
            'published_inputs': published, 'readiness_controls': refs, 'current_batch': json.loads((ROOT / 'prepare-batch-admitted.json').read_text()), 'conformance': conformance, 'uv_options': uv,
            'owned_container_cleanup': cleanup, 'prior_codegraph_json_files_unchanged': preserved,
            'native_grading_controls': {'original_selected_controls': 6, 'adapter_source_unchanged_from_v1': True},
            'development_failures': {'return_value_unpack': 'The driver command returns (code, output); the first identity query passed the tuple to json.loads. Its original failure remains recorded.', 'metadata_scope': 'A product identity scan from the target checkout picked up that project egg-info. The query now runs from /opt, matching the original identity audit. No product dependency change is hidden by this correction.'},
            'model_inference_sessions': 0, 'external_participants': 0}
ref = write('codegraph_matched_v2_admission_2026_10_28.json', artifact)
print(json.dumps({'index': ref['artifact'], 'readiness_controls': len(refs), 'final_driver_preparations_passed': 12, 'all_owned_containers_absent': len(cleanup), 'prior_json_files_unchanged': len(preserved), 'new_model_sessions': 0}))
